package com.gandhre.demo.platform.event;import java.time.Instant;import java.util.UUID;import org.springframework.stereotype.Service;@Servicepublic class EventService {	private final EventPublisher publisher;	public EventService(EventPublisher publisher) {		this.publisher = publisher;	}	public ProcessingEvent create(CreateEventRequest request) {		ProcessingEvent event = new ProcessingEvent(UUID.randomUUID(), request.eventType(), request.aggregateId(),				request.payload(), Instant.now());		publisher.publish(event);		return event;	}}